/* YSF transmitter tests: the TX sequence builder (ysf_tx_frame_build) and
 * streamer (ysf_tx) against the frame decoder and, through the simulated FM
 * channel, against the RX demodulator from phase 1.
 *
 * Vectors are generated by our own encoder, as in test_ysf_modem.c: there
 * are no public YSF test vectors. The Data FR second DCH is additionally
 * cross-checked against MMDVMHost in test_ysf_mmdvm.cc.
 *
 *   test_ysf_tx            assertions (CI) */
#include "ysf_frame.h"
#include "ysf_modem.h"
#include "ysf_tx.h"
#include "ysf_channel.h"
#include <assert.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define LEAD_S 0.1
enum { TXG = 512 };   /* modulator output: 2 LSB per Hz, as in test_ysf_modem.c */
enum { MAX_DIB = 20000, MAX_SAMP = 60000 };

static unsigned checks, failures;
#define CHECK(c) do { checks++; if (!(c)) { failures++; fprintf(stderr, "FAIL %s:%d: %s\n", __FILE__, __LINE__, #c); } } while (0)

static uint8_t txdib[MAX_DIB], rxdib[MAX_DIB];
static int16_t tx8[MAX_SAMP], rx8[MAX_SAMP];

/* Test identity: XE1ARS, DG-ID 42. */
static void test_data(void *ctx, unsigned index, uint8_t out[20])
{
    (void)ctx;
    out[0] = 'D'; out[1] = 'T';
    out[2] = (uint8_t)('0' + (index / 10) % 10);
    out[3] = (uint8_t)('0' + index % 10);
    for (unsigned i = 4; i < 20; i++) out[i] = (uint8_t)(index * 20 + i);
}

/* Test voice blocks: a deterministic pattern that differs per frame and
 * block, so a swapped or dropped block is caught. NOT AMBE: the real voice
 * path (49-bit parameters -> 72-bit VCH) is a separate problem. */
static void test_voice(void *ctx, unsigned frame_no, unsigned block, uint8_t *vch, unsigned vch_len)
{
    (void)ctx;
    for (unsigned i = 0; i < vch_len; i++) vch[i] = (uint8_t)(0x40 + frame_no * 5 + block * 3 + i);
}

static ysf_tx_config mkcfg(uint8_t dt, uint8_t dev)
{
    ysf_tx_config c;
    memset(&c, 0, sizeof c);
    c.dt = dt;
    c.dev = dev;
    c.cm = YSF_CM_GROUP;
    c.mr = YSF_MR_DIRECT;
    c.dgid = 42;
    memcpy(c.dest, "CQ        ", 10);
    memcpy(c.src, "XE1ARS    ", 10);
    memcpy(c.down, "XE1ARS-R  ", 10);
    memcpy(c.up, "XE1ARS    ", 10);
    memcpy(c.rem1, "REM1      ", 10);
    memcpy(c.rem2, "REM2      ", 10);
    memcpy(c.rem3, "REM3      ", 10);
    memcpy(c.rem4, "REM4      ", 10);
    c.cycles = 1;
    c.gain_q8 = TXG;
    c.data = test_data;
    c.voice = test_voice;
    return c;
}

static unsigned voice_len_of(uint8_t dt)
{
    switch (dt) {
    case YSF_DT_VD_MODE1: return 9;
    case YSF_DT_VD_MODE2: return 13;
    case YSF_DT_VOICE_FR: return 18;
    default: return 0;
    }
}

static unsigned voice_off_of(uint8_t dt, unsigned b)
{
    switch (dt) {
    case YSF_DT_VD_MODE1: return 18 * b + 9;
    case YSF_DT_VD_MODE2: return 18 * b + 5;
    case YSF_DT_VOICE_FR: return 18 * b;
    default: return 0;
    }
}

/* Expected data unit for index (mirrors test_data). */
static void expect_data(unsigned index, uint8_t out[20])
{
    test_data(NULL, index, out);
}

/* Check one built frame's FICH, DCH and voice blocks. */
static void check_frame(const ysf_tx_config *c, unsigned frame_no, const uint8_t frame[YSF_FRAME_BYTES])
{
    ysf_fich f;
    uint8_t dch[20], dch2[20];
    unsigned dlen = 0;
    bool ok = ysf_frame_decode(frame, &f, dch, dch2, &dlen);
    CHECK(ok);
    if (!ok) return;
    unsigned total = ysf_tx_total_frames(c);
    unsigned expect_fi = frame_no == 0 ? YSF_FI_HEADER : frame_no == total - 1 ? YSF_FI_TERMINATOR : YSF_FI_COMMUNICATION;
    CHECK(f.fi == expect_fi);
    CHECK(f.dt == c->dt);
    CHECK(f.dev == c->dev);
    CHECK(f.sc == c->dgid);
    CHECK(f.cm == c->cm && f.mr == c->mr);
    unsigned fn = (frame_no == 0 || frame_no == total - 1) ? 0 : (frame_no - 1) % 8;
    if (f.fi == YSF_FI_COMMUNICATION) CHECK(f.fn == fn);

    uint8_t expect[20], expect2[20];
    if (f.fi == YSF_FI_HEADER || f.fi == YSF_FI_TERMINATOR) {
        CHECK(dlen == 20);
        memcpy(expect, "CQ        XE1ARS    ", 20);
        memcpy(expect2, "XE1ARS-R  XE1ARS    ", 20);
        CHECK(!memcmp(dch, expect, 20) && !memcmp(dch2, expect2, 20));
        return;
    }
    switch (c->dt) {
    case YSF_DT_VD_MODE1:
        CHECK(dlen == 20);
        if (fn == 0) memcpy(expect, "CQ        XE1ARS    ", 20);
        else if (fn == 1) memcpy(expect, "XE1ARS-R  XE1ARS    ", 20);
        else if (fn == 2) memcpy(expect, "REM1      REM2      ", 20);
        else expect_data(fn - 3, expect);
        CHECK(!memcmp(dch, expect, 20));
        break;
    case YSF_DT_VD_MODE2:
        CHECK(dlen == 10);
        if (fn == 0) memcpy(expect, "CQ        ", 10);
        else if (fn == 1) memcpy(expect, "XE1ARS    ", 10);
        else if (fn == 2) memcpy(expect, "XE1ARS-R  ", 10);
        else if (fn == 3) memcpy(expect, "XE1ARS    ", 10);
        else if (fn == 4) memcpy(expect, "REM1 REM2 ", 10);
        else if (fn == 5) memcpy(expect, "REM3 REM4 ", 10);
        else expect_data(fn - 6, expect);
        CHECK(!memcmp(dch, expect, 10));
        break;
    case YSF_DT_DATA_FR:
        CHECK(dlen == 20);
        if (fn == 0) {
            memcpy(expect, "CQ        XE1ARS    ", 20);
            memcpy(expect2, "XE1ARS-R  XE1ARS    ", 20);
        } else if (fn == 1) {
            memcpy(expect, "REM1      REM2      ", 20);
            expect_data(0, expect2);
        } else {
            expect_data(2 * fn - 3, expect);
            expect_data(2 * fn - 2, expect2);
        }
        CHECK(!memcmp(dch, expect, 20) && !memcmp(dch2, expect2, 20));
        break;
    default: /* VW: no DCH */
        CHECK(dlen == 0);
        break;
    }
    /* Voice blocks: the callback's bytes, byte for byte. */
    unsigned vlen = voice_len_of(c->dt);
    if (vlen) {
        const uint8_t *payload = frame + YSF_SYNC_BYTES + YSF_FICH_BYTES;
        for (unsigned b = 0; b < YSF_BLOCKS; b++) {
            uint8_t want[18];
            test_voice(NULL, frame_no, b, want, vlen);
            CHECK(!memcmp(payload + voice_off_of(c->dt, b), want, vlen));
        }
    }
}

static void check_mode(uint8_t dt, uint8_t dev)
{
    ysf_tx_config c = mkcfg(dt, dev);
    unsigned total = ysf_tx_total_frames(&c);
    CHECK(total == 10);
    fprintf(stderr, "mode DT %u dev %u: %u frames\n", dt, dev, total);
    for (unsigned k = 0; k < total; k++) {
        uint8_t frame[YSF_FRAME_BYTES];
        CHECK(ysf_tx_frame_build(&c, k, frame));
        check_frame(&c, k, frame);
    }
    uint8_t frame[YSF_FRAME_BYTES];
    CHECK(!ysf_tx_frame_build(&c, total, frame));   /* past the terminator */
}

static ysf_channel_cfg chcfg(double cnr, uint64_t seed)
{
    ysf_channel_cfg c = { cnr, 0, 1.0, 0, 0, 0, 8.0, 0, LEAD_S, seed };
    return c;
}

/* Stream one transmission through the channel and verify every frame on the
 * RX side. voice_max_err: allowed voice-region bit errors over the whole
 * transmission (voice has no FEC: 0 clean, a few at C/N 20, more at C/N 10). */
static void run_tx(const ysf_tx_config *c, const ysf_channel_cfg *ch, unsigned voice_max_err, const char *label)
{
    unsigned total = ysf_tx_total_frames(c);
    uint8_t frames[10][YSF_FRAME_BYTES];
    for (unsigned k = 0; k < total; k++) CHECK(ysf_tx_frame_build(c, k, frames[k]));

    ysf_tx t;
    ysf_tx_init(&t, c);
    size_t n8 = 0;
    int16_t chunk[1024];
    while (!ysf_tx_done(&t)) {
        size_t n = ysf_tx_samples(&t, chunk, sizeof chunk / sizeof *chunk);
        if (!n) break;
        assert(n8 + n < MAX_SAMP);
        memcpy(tx8 + n8, chunk, n * sizeof *chunk);
        n8 += n;
    }
    CHECK(ysf_tx_done(&t));
    /* Harness tail, as in test_ysf_modem.c: extra symbols so the demodulator's
     * matched-filter span covers the last frame's symbols too. */
    ysf_mod m;
    ysf_mod_init(&m, c->dev ? TXG / 2 : TXG);
    for (unsigned i = 0; i < 48; i++) n8 += ysf_mod_dibit(&m, (i & 1) ? 3 : 1, tx8 + n8);
    n8 += ysf_mod_flush(&m, tx8 + n8);
    assert(n8 < MAX_SAMP);
    n8 = ysf_channel_run(ch, tx8, n8, TXG / 256.0, rx8);

    ysf_demod d;
    ysf_demod_init(&d);
    size_t lead8 = (size_t)(ch->lead_s * 8000), open = lead8;
    size_t nd = ysf_demod_samples(&d, rx8, open, rxdib, MAX_DIB);
    ysf_demod_reacquire(&d);
    nd += ysf_demod_samples(&d, rx8 + open, n8 - open, rxdib + nd, MAX_DIB - nd);

    size_t first = ysf_find_sync(rxdib, nd, YSF_SYNC_MAX_ERRORS);
    fprintf(stderr, "%s: first sync at %zu (nd %zu)\n", label, first, nd);
    CHECK(first != SIZE_MAX && first >= 480 - 4 && first <= 480 + 24 + 4);
    if (first == SIZE_MAX) return;
    unsigned voice_err = 0;
    for (unsigned k = 0; k < total; k++) {
        size_t pos = first + (size_t)k * YSF_FRAME_DIBITS;
        if (k > 0) {
            size_t found = ysf_find_sync(rxdib + pos - 4, 28, YSF_SYNC_MAX_ERRORS);
            CHECK(found != SIZE_MAX);
            if (found == SIZE_MAX) continue;
            pos = pos - 4 + found;
        }
        CHECK(pos + YSF_FRAME_DIBITS <= nd);
        if (pos + YSF_FRAME_DIBITS > nd) continue;
        uint8_t frame[YSF_FRAME_BYTES];
        ysf_dibits_to_bytes(rxdib + pos, YSF_FRAME_DIBITS, frame);
        ysf_fich f;
        uint8_t dch[20], dch2[20];
        unsigned dlen = 0;
        bool ok = ysf_frame_decode(frame, &f, dch, dch2, &dlen);
        fprintf(stderr, "%s frame %u: decode %d FI %u DT %u FN %u Dev %u DG %u\n", label, k, ok, f.fi, f.dt, f.fn, f.dev, f.sc);
        CHECK(ok);
        if (!ok) continue;
        CHECK(f.fi == (k == 0 ? YSF_FI_HEADER : k == total - 1 ? YSF_FI_TERMINATOR : YSF_FI_COMMUNICATION));
        CHECK(f.dt == c->dt && f.dev == c->dev && f.sc == c->dgid);
        if (f.fi == YSF_FI_COMMUNICATION) CHECK(f.fn == (k - 1) % 8);
        /* DCH contents against the transmitted frame's decode. */
        ysf_fich tf;
        uint8_t tdch[20], tdch2[20];
        unsigned tdlen = 0;
        CHECK(ysf_frame_decode(frames[k], &tf, tdch, tdch2, &tdlen));
        CHECK(dlen == tdlen && !memcmp(dch, tdch, dlen));
        if (c->dt == YSF_DT_DATA_FR || f.fi == YSF_FI_HEADER || f.fi == YSF_FI_TERMINATOR)
            CHECK(!memcmp(dch2, tdch2, 20));
        /* Voice-region bit errors against the transmitted frame. */
        unsigned vlen = voice_len_of(c->dt);
        if (vlen && f.fi == YSF_FI_COMMUNICATION) {
            const uint8_t *rp = frame + YSF_SYNC_BYTES + YSF_FICH_BYTES;
            const uint8_t *tp = frames[k] + YSF_SYNC_BYTES + YSF_FICH_BYTES;
            for (unsigned b = 0; b < YSF_BLOCKS; b++) {
                unsigned off = voice_off_of(c->dt, b);
                for (unsigned i = 0; i < vlen; i++) {
                    uint8_t x = (uint8_t)(rp[off + i] ^ tp[off + i]);
                    while (x) { voice_err += x & 1u; x >>= 1; }
                }
            }
        }
    }
    fprintf(stderr, "%s: voice bit errors %u (max %u)\n", label, voice_err, voice_max_err);
    CHECK(voice_err <= voice_max_err);
}

int main(void)
{
    /* Sequence builder: all four modes, wide and narrow, frame by frame. */
    check_mode(YSF_DT_VD_MODE1, 0);
    check_mode(YSF_DT_VD_MODE2, 0);
    check_mode(YSF_DT_DATA_FR, 0);
    check_mode(YSF_DT_VOICE_FR, 0);
    check_mode(YSF_DT_VD_MODE1, 1);   /* narrow: Dev bit set on every frame */
    check_mode(YSF_DT_VD_MODE2, 1);

    /* Out of range / unknown mode. */
    {
        ysf_tx_config c = mkcfg(YSF_DT_VD_MODE1, 0);
        uint8_t frame[YSF_FRAME_BYTES];
        CHECK(!ysf_tx_frame_build(&c, 10, frame));
        c.dt = 99;
        CHECK(!ysf_tx_frame_build(&c, 0, frame));
        ysf_tx t;
        ysf_tx_init(&t, &c);
        CHECK(ysf_tx_done(&t));
        uint8_t dib[16];
        CHECK(ysf_tx_dibits(&t, dib, sizeof dib) == 0);
        int16_t s[16];
        CHECK(ysf_tx_samples(&t, s, 16) == 0);
    }

    /* Silence: no voice callback -> voice blocks are all zero. */
    {
        ysf_tx_config c = mkcfg(YSF_DT_VD_MODE1, 0);
        c.voice = NULL;
        uint8_t frame[YSF_FRAME_BYTES];
        CHECK(ysf_tx_frame_build(&c, 1, frame));
        const uint8_t *p = frame + YSF_SYNC_BYTES + YSF_FICH_BYTES;
        bool allzero = true;
        for (unsigned b = 0; b < YSF_BLOCKS; b++)
            for (unsigned i = 0; i < 9; i++) allzero &= p[18 * b + 9 + i] == 0;
        CHECK(allzero);
        c.dt = YSF_DT_VOICE_FR;
        CHECK(ysf_tx_frame_build(&c, 1, frame));
        allzero = true;
        for (unsigned i = 0; i < YSF_PAYLOAD_BYTES; i++) allzero &= p[i] == 0;
        CHECK(allzero);
    }

    /* Streamer fidelity: dibits, sample count, small-chunk streaming. */
    {
        ysf_tx_config c = mkcfg(YSF_DT_VD_MODE1, 0);
        uint8_t want[MAX_DIB];
        unsigned ndib = 0;
        for (unsigned k = 0; k < 10; k++) {
            uint8_t frame[YSF_FRAME_BYTES];
            CHECK(ysf_tx_frame_build(&c, k, frame));
            ysf_bytes_to_dibits(frame, YSF_FRAME_BYTES, want + ndib);
            ndib += YSF_FRAME_DIBITS;
        }
        ysf_tx t;
        ysf_tx_init(&t, &c);
        unsigned got = 0;
        while (!ysf_tx_done(&t)) {
            size_t n = ysf_tx_dibits(&t, txdib + got, MAX_DIB - got);
            if (!n) break;
            got += (unsigned)n;
        }
        CHECK(got == ndib);
        CHECK(!memcmp(txdib, want, ndib));

        /* Samples, one big buffer: 4800 dibits x 5/3 = 8000 samples (+1). */
        ysf_tx_init(&t, &c);
        size_t n8 = 0;
        while (!ysf_tx_done(&t)) {
            size_t n = ysf_tx_samples(&t, tx8 + n8, MAX_SAMP - n8);
            if (!n) break;
            n8 += n;
        }
        CHECK(ysf_tx_done(&t));
        fprintf(stderr, "streamer: %u dibits -> %zu samples\n", ndib, n8);
        CHECK(n8 >= 8000 && n8 <= 8001);
        CHECK(ysf_tx_samples(&t, tx8, 16) == 0);

        /* Same stream in 7-sample chunks: identical samples, no loss. */
        static int16_t small[MAX_SAMP];
        ysf_tx_init(&t, &c);
        size_t n8s = 0;
        while (!ysf_tx_done(&t)) {
            size_t n = ysf_tx_samples(&t, small + n8s, 7);
            if (!n) break;
            n8s += n;
        }
        CHECK(n8s == n8);
        CHECK(!memcmp(small, tx8, n8 * sizeof *tx8));

        /* Two cycles: 18 frames, 8640 dibits. */
        c.cycles = 2;
        CHECK(ysf_tx_total_frames(&c) == 18);
        ysf_tx_init(&t, &c);
        got = 0;
        while (!ysf_tx_done(&t)) {
            size_t n = ysf_tx_dibits(&t, txdib + got, MAX_DIB - got);
            if (!n) break;
            got += (unsigned)n;
        }
        CHECK(got == 18 * YSF_FRAME_DIBITS);
        /* The repeated block keeps FN 0..7 twice, terminator last. */
        uint8_t frame[YSF_FRAME_BYTES];
        CHECK(ysf_tx_frame_build(&c, 9, frame));
        ysf_fich f;
        uint8_t dch[20], dch2[20];
        unsigned dlen = 0;
        CHECK(ysf_frame_decode(frame, &f, dch, dch2, &dlen));
        CHECK(f.fi == YSF_FI_COMMUNICATION && f.fn == 0);
        CHECK(ysf_tx_frame_build(&c, 17, frame));
        CHECK(ysf_frame_decode(frame, &f, dch, dch2, &dlen));
        CHECK(f.fi == YSF_FI_TERMINATOR);
    }

    /* Narrow halves the deviation: same dibit stream, peak |sample| ratio ~2. */
    {
        ysf_tx_config cw = mkcfg(YSF_DT_VD_MODE1, 0), cn = mkcfg(YSF_DT_VD_MODE1, 1);
        int32_t peak_w = 0, peak_n = 0;
        for (unsigned k = 0; k < 2; k++) {
            ysf_tx t;
            ysf_tx_init(&t, k ? &cn : &cw);
            size_t n8 = 0;
            while (!ysf_tx_done(&t)) {
                size_t n = ysf_tx_samples(&t, tx8 + n8, MAX_SAMP - n8);
                if (!n) break;
                n8 += n;
            }
            int32_t peak = 0;
            for (size_t i = 0; i < n8; i++) {
                int32_t a = tx8[i] < 0 ? -tx8[i] : tx8[i];
                if (a > peak) peak = a;
            }
            if (k) peak_n = peak; else peak_w = peak;
        }
        fprintf(stderr, "deviation peaks: wide %d narrow %d ratio %.2f\n",
                peak_w, peak_n, peak_n ? (double)peak_w / peak_n : 0);
        CHECK(peak_w > 4000 && peak_n > 2000);
        CHECK(peak_n && (double)peak_w / peak_n > 1.8 && (double)peak_w / peak_n < 2.2);
    }

    /* Loopback through the FM channel: clean, C/N 20 dB, C/N 10 dB. */
    ysf_channel_cfg ch;
    ysf_tx_config c;
    c = mkcfg(YSF_DT_VD_MODE1, 0);
    ch = chcfg(300, 11);
    run_tx(&c, &ch, 0, "tx vd1 clean");
    ch = chcfg(20, 12);
    run_tx(&c, &ch, 16, "tx vd1 C/N 20 dB");
    ch = chcfg(10, 13);
    run_tx(&c, &ch, 144, "tx vd1 C/N 10 dB");
    c = mkcfg(YSF_DT_VD_MODE2, 0);
    ch = chcfg(300, 14);
    run_tx(&c, &ch, 0, "tx dn clean");
    ch = chcfg(20, 15);
    run_tx(&c, &ch, 24, "tx dn C/N 20 dB");
    ch = chcfg(10, 16);
    run_tx(&c, &ch, 208, "tx dn C/N 10 dB");
    c = mkcfg(YSF_DT_DATA_FR, 0);
    ch = chcfg(300, 17);
    run_tx(&c, &ch, 0, "tx data-fr clean");
    ch = chcfg(20, 18);
    run_tx(&c, &ch, 0, "tx data-fr C/N 20 dB");
    ch = chcfg(10, 19);
    run_tx(&c, &ch, 0, "tx data-fr C/N 10 dB");
    c = mkcfg(YSF_DT_VOICE_FR, 0);
    ch = chcfg(300, 20);
    run_tx(&c, &ch, 0, "tx vw clean");
    c = mkcfg(YSF_DT_VD_MODE1, 1);
    ch = chcfg(300, 21);
    run_tx(&c, &ch, 0, "tx vd1 narrow clean");
    ch = chcfg(20, 22);
    run_tx(&c, &ch, 16, "tx vd1 narrow C/N 20 dB");

    fprintf(stderr, "checks %u failures %u\n", checks, failures);
    assert(failures == 0);
    printf("PASS YSF TX: %u checks, TX sequences (V/D-1, DN, Data FR, VW, narrow) through the FM channel "
           "(clean, C/N 20 dB, C/N 10 dB)\n",
           checks);
    return 0;
}
